function blake2bCompress (ctx, last) {
  let i = 0

  // init work variables
  for (i = 0; i < 16; i++) {
    v[i] = ctx.h[i]
    v[i + 16] = BLAKE2B_IV32[i]
  }

  // low 64 bits of offset
  v[24] = v[24] ^ ctx.t
  v[25] = v[25] ^ (ctx.t / 0x100000000)
  // high 64 bits not supported, offset may not be higher than 2**53-1

  // last block flag set ?
  if (last) {
    v[28] = ~v[28]
    v[29] = ~v[29]
  }

  // get little-endian words
  for (i = 0; i < 32; i++) {
    m[i] = B2B_GET32(ctx.b, 4 * i)
  }

  // twelve rounds of mixing
  // uncomment the DebugPrint calls to log the computation
  // and match the RFC sample documentation
  // util.debugPrint('          m[16]', m, 64)
  for (i = 0; i < 12; i++) {
    // util.debugPrint('   (i=' + (i < 10 ? ' ' : '') + i + ') v[16]', v, 64)
    B2B_G(0, 8, 16, 24, SIGMA82[i * 16 + 0], SIGMA82[i * 16 + 1])
    B2B_G(2, 10, 18, 26, SIGMA82[i * 16 + 2], SIGMA82[i * 16 + 3])
    B2B_G(4, 12, 20, 28, SIGMA82[i * 16 + 4], SIGMA82[i * 16 + 5])
    B2B_G(6, 14, 22, 30, SIGMA82[i * 16 + 6], SIGMA82[i * 16 + 7])
    B2B_G(0, 10, 20, 30, SIGMA82[i * 16 + 8], SIGMA82[i * 16 + 9])
    B2B_G(2, 12, 22, 24, SIGMA82[i * 16 + 10], SIGMA82[i * 16 + 11])
    B2B_G(4, 14, 16, 26, SIGMA82[i * 16 + 12], SIGMA82[i * 16 + 13])
    B2B_G(6, 8, 18, 28, SIGMA82[i * 16 + 14], SIGMA82[i * 16 + 15])
  }
  // util.debugPrint('   (i=12) v[16]', v, 64)

  for (i = 0; i < 16; i++) {
    ctx.h[i] = ctx.h[i] ^ v[i] ^ v[i + 16]
  }
  // util.debugPrint('h[8]', ctx.h, 64)
}

// reusable parameterBlock
const parameterBlock = new Uint8Array([
  0,
  0,
  0,
  0, //  0: outlen, keylen, fanout, depth
  0,
  0,
  0,
  0, //  4: leaf length, sequential mode
  0,
  0,
  0,
  0, //  8: node offset
  0,
  0,
  0,
  0, // 12: node offset
  0,
  0,
  0,
  0, // 16: node depth, inner length, rfu
  0,
  0,
  0,
  0, // 20: rfu
  0,
  0,
  0,
  0, // 24: rfu
  0,
  0,
  0,
  0, // 28: rfu
  0,
  0,
  0,
  0, // 32: salt
  0,
  0,
  0,
  0, // 36: salt
  0,
  0,
  0,
  0, // 40: salt
  0,
  0,
  0,
  0, // 44: salt
  0,
  0,
  0,
  0, // 48: personal
  0,
  0,
  0,
  0, // 52: personal
  0,
  0,
  0,
  0, // 56: personal
  0,
  0,
  0,
  0 // 60: personal
])

// Creates a BLAKE2b hashing context
// Requires an output length between 1 and 64 bytes
// Takes an optional Uint8Array key
// Takes an optinal Uint8Array salt
// Takes an optinal Uint8Array personal
function blake2bInit (outlen, key, salt, personal) {
  if (outlen === 0 || outlen > 64) {
    throw new Error('Illegal output length, expected 0 < length <= 64')
  }
  if (key && key.length > 64) {
    throw new Error('Illegal key, expected Uint8Array with 0 < length <= 64')
  }
  if (salt && salt.length !== 16) {
    throw new Error('Illegal salt, expected Uint8Array with length is 16')
  }
  if (personal && personal.length !== 16) {
    throw new Error('Illegal personal, expected Uint8Array with length is 16')
  }

  // state, 'param block'
  const ctx = {
    b: new Uint8Array(128),
    h: new Uint32Array(16),
    t: 0, // input count
    c: 0, // pointer within buffer
    outlen: outlen // output length in bytes
  }

  // initialize parameterBlock before usage
  parameterBlock.fill(0)
  parameterBlock[0] = outlen
  if (key) parameterBlock[1] = key.length
  parameterBlock[2] = 1 // fanout
  parameterBlock[3] = 1 // depth
  if (salt) parameterBlock.set(salt, 32)
  if (personal) parameterBlock.set(personal, 48)

  // initialize hash state
  for (let i = 0; i < 16; i++) {
    ctx.h[i] = BLAKE2B_IV32[i] ^ B2B_GET32(parameterBlock, i * 4)
  }

  // key the hash, if applicable
  if (key) {
    blake2bUpdate(ctx, key)
    // at the end
    ctx.c = 128
  }

  return ctx
}

// Updates a BLAKE2b streaming hash
// Requires hash context and Uint8Array (byte array)
function blake2bUpdate (ctx, input) {
  for (let i = 0; i < input.length; i++) {
    if (ctx.c === 128) {
      // buffer full ?
      ctx.t += ctx.c // add counters
      blake2bCompress(ctx, false) // compress (not last)
      ctx.c = 0 // counter to zero
    }
    ctx.b[ctx.c++] = input[i]
  }
}

// Completes a BLAKE2b streaming hash
// Returns a Uint8Array containing the message digest
function blake2bFinal (ctx) {
  ctx.t += ctx.c // mark last block offset

  while (ctx.c < 128) {
    // fill up with zeros
    ctx.b[ctx.c++] = 0
  }
  blake2bCompress(ctx, true) // final block flag = 1

  // little endian convert and store
  const out = new Uint8Array(ctx.outlen)
  for (let i = 0; i < ctx.outlen; i++) {
    out[i] = ctx.h[i >> 2] >> (8 * (i & 3))
  }
  return out
}

// Computes the BLAKE2B hash of a string or byte array, and returns a Uint8Array
//
// Returns a n-byte Uint8Array
//
// Parameters:
// - input - the input bytes, as a string, Buffer or Uint8Array
// - key - optional key Uint8Array, up to 64 bytes
// - outlen - optional output length in bytes, default 64
// - salt - optional salt bytes, string, Buffer or Uint8Array
// - personal - optional personal bytes, string, Buffer or Uint8Array
function blake2b (input, key, outlen, salt, personal) {
  // preprocess inputs
  outlen = outlen || 64
  input = util.normalizeInput(input)
  if (salt) {
    salt = util.normalizeInput(salt)
  }
  if (personal) {
    personal = util.normalizeInput(personal)
  }

  // do the math
  const ctx = blake2bInit(outlen, key, salt, personal)
  blake2bUpdate(ctx, input)
  return blake2bFinal(ctx)
}

// Computes the BLAKE2B hash of a string or byte array
//
// Returns an n-byte hash in hex, all lowercase
//
// Parameters:
// - input - the input bytes, as a string, Buffer, or Uint8Array
// - key - optional key Uint8Array, up to 64 bytes
// - outlen - optional output length in bytes, default 64
// - salt - optional salt bytes, string, Buffer or Uint8Array
// - personal - optional personal bytes, string, Buffer or Uint8Array
function blake2bHex (input, key, outlen, salt, personal) {
  const output = blake2b(input, key, outlen, salt, personal)
  return util.toHex(output)
}

(function () {
// ===== 同步逻辑（上面是 tweetnacl + tweetnacl-util + blakejs，不要改）=====
// 把 BoxJs 里的签到账号上传到 GitHub 仓库的 Secrets
// 用法：先在 BoxJs 里填好 GitHub Token 和仓库，然后在 Loon 里点这个脚本手动运行一次
// Token 在 GitHub 上创建：Settings → Developer settings → Personal access tokens
// → Fine-grained tokens → 选 Only select repositories → loon-plugins
// → Repository permissions 里 Secrets 选 Read and write
// 上传走 HTTPS 直连 GitHub，账号不会经过任何第三方

var PAT_KEY = "github_pat";
var REPO_KEY = "github_repo";

// BoxJs 键 → GitHub Secret 名（和 actions/checkin.mjs 里读的名字一致）
var MAPPING = [
  ["woniu_cookie", "WONIU_COOKIE"],
  ["woniu_username", "WONIU_USERNAME"],
  ["woniu_password", "WONIU_PASSWORD"],
  ["woniu_cookie2", "WONIU_COOKIE2"],
  ["woniu_username2", "WONIU_USERNAME2"],
  ["woniu_password2", "WONIU_PASSWORD2"],
  ["woniu_cookie3", "WONIU_COOKIE3"],
  ["woniu_username3", "WONIU_USERNAME3"],
  ["woniu_password3", "WONIU_PASSWORD3"],
  ["woniu_accounts", "WONIU_ACCOUNTS"],
  ["embypulse1_session_id", "LEWA_SESSION_ID"],
  ["embypulse1_username", "LEWA_USERNAME"],
  ["embypulse1_password", "LEWA_PASSWORD"],
  ["embypulse1_session_id2", "LEWA_SESSION_ID2"],
  ["embypulse1_username2", "LEWA_USERNAME2"],
  ["embypulse1_password2", "LEWA_PASSWORD2"],
  ["embypulse1_session_id3", "LEWA_SESSION_ID3"],
  ["embypulse1_username3", "LEWA_USERNAME3"],
  ["embypulse1_password3", "LEWA_PASSWORD3"],
  ["embypulse1_accounts", "LEWA_ACCOUNTS"],
  ["embypulse2_session_id", "LEGUAN_SESSION_ID"],
  ["embypulse2_username", "LEGUAN_USERNAME"],
  ["embypulse2_password", "LEGUAN_PASSWORD"],
  ["embypulse2_session_id2", "LEGUAN_SESSION_ID2"],
  ["embypulse2_username2", "LEGUAN_USERNAME2"],
  ["embypulse2_password2", "LEGUAN_PASSWORD2"],
  ["embypulse2_session_id3", "LEGUAN_SESSION_ID3"],
  ["embypulse2_username3", "LEGUAN_USERNAME3"],
  ["embypulse2_password3", "LEGUAN_PASSWORD3"],
  ["embypulse2_accounts", "LEGUAN_ACCOUNTS"],
  ["chilledmelon_username", "CHILLEDMELON_USERNAME"],
  ["chilledmelon_password", "CHILLEDMELON_PASSWORD"],
  ["chilledmelon_username2", "CHILLEDMELON_USERNAME2"],
  ["chilledmelon_password2", "CHILLEDMELON_PASSWORD2"],
  ["chilledmelon_username3", "CHILLEDMELON_USERNAME3"],
  ["chilledmelon_password3", "CHILLEDMELON_PASSWORD3"],
  ["chilledmelon_accounts", "CHILLEDMELON_ACCOUNTS"],
  ["glados_cookie", "GLADOS_COOKIE"],
  ["glados_cookie2", "GLADOS_COOKIE2"],
  ["glados_cookie3", "GLADOS_COOKIE3"],
  ["glados_ua", "GLADOS_UA"],
  ["glados_accounts", "GLADOS_ACCOUNTS"],
  ["glados_exchange", "GLADOS_EXCHANGE"],
  ["netease_cookie", "NETEASE_COOKIE"],
  ["netease_cookie2", "NETEASE_COOKIE2"],
  ["netease_cookie3", "NETEASE_COOKIE3"],
  ["netease_accounts", "NETEASE_ACCOUNTS"]
];

function read(k) { return $persistentStore.read(k) || ""; }

// Loon 里没有密码学随机数，用时间 + Math.random 混在一起生成一次性临时密钥
// 这个临时密钥只在手机上用一次、不会发给任何人，加密结果走 HTTPS 发给 GitHub
nacl.setPRNG(function (x, n) {
  var t = Date.now();
  for (var i = 0; i < n; i++) {
    var r = Math.floor(Math.random() * 256);
    var r2 = Math.floor(Math.random() * 256);
    x[i] = (r ^ r2 ^ ((t >> ((i % 4) * 8)) & 0xff) ^ i) & 0xff;
  }
});

var B64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
function b64encode(bytes) {
  var out = "";
  for (var i = 0; i < bytes.length; i += 3) {
    var b0 = bytes[i], b1 = i + 1 < bytes.length ? bytes[i + 1] : 0, b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    out += B64_CHARS[b0 >> 2];
    out += B64_CHARS[((b0 & 3) << 4) | (b1 >> 4)];
    out += i + 1 < bytes.length ? B64_CHARS[((b1 & 15) << 2) | (b2 >> 6)] : "=";
    out += i + 2 < bytes.length ? B64_CHARS[b2 & 63] : "=";
  }
  return out;
}
function b64decode(str) {
  var clean = str.replace(/-/g, "+").replace(/_/g, "/").replace(/[^A-Za-z0-9+/=]/g, "");
  var out = [];
  for (var i = 0; i < clean.length; i += 4) {
    var v0 = B64_CHARS.indexOf(clean.charAt(i));
    var v1 = B64_CHARS.indexOf(clean.charAt(i + 1));
    var v2 = clean.charAt(i + 2) === "=" ? 0 : B64_CHARS.indexOf(clean.charAt(i + 2));
    var v3 = clean.charAt(i + 3) === "=" ? 0 : B64_CHARS.indexOf(clean.charAt(i + 3));
    out.push((v0 << 2) | (v1 >> 4));
    if (clean.charAt(i + 2) !== "=") out.push(((v1 & 15) << 4) | (v2 >> 2));
    if (clean.charAt(i + 3) !== "=") out.push(((v2 & 3) << 6) | v3);
  }
  return new Uint8Array(out);
}

// GitHub Secrets 要求的密封盒加密（和 GitHub 服务端用的 libsodium 完全一致）
function sealSecret(messageBytes, recipientPk) {
  var epk = nacl.box.keyPair();
  var input = new Uint8Array(64);
  input.set(epk.publicKey, 0);
  input.set(recipientPk, 32);
  var nonce = blake2b(input, null, 24);
  var boxed = nacl.box(messageBytes, nonce, recipientPk, epk.secretKey);
  var out = new Uint8Array(32 + boxed.length);
  out.set(epk.publicKey, 0);
  out.set(boxed, 32);
  return out;
}

function parseJson(d) { try { return JSON.parse(d); } catch (e) { return null; } }

var pat = read(PAT_KEY);
var repo = read(REPO_KEY);
var synced = [], skipped = [], failed = [];
var queue = [];

if (!pat) {
  $notification.post("同步Git Secrets", "还没填 GitHub Token", "在 BoxJs 里填 Token，创建方法看简介栏");
  $done({});
} else if (!repo) {
  $notification.post("同步Git Secrets", "还没填仓库", "在 BoxJs 里填仓库，格式：用户名/仓库名");
  $done({});
} else if (repo.indexOf("/") === -1) {
  $notification.post("同步Git Secrets", "仓库格式不对", "仓库要填 用户名/仓库名，例如 Crack22/loon-plugins");
  $done({});
} else {
  for (var i = 0; i < MAPPING.length; i++) {
    var v = read(MAPPING[i][0]);
    if (v) queue.push({ key: MAPPING[i][0], name: MAPPING[i][1], value: v });
    else skipped.push(MAPPING[i][1]);
  }
  if (!queue.length) {
    $notification.post("同步Git Secrets", "BoxJs 里没有账号", "先在签到应用里填好 Cookie 或账号密码");
    $done({});
  } else {
    $httpClient.get({
      url: "https://api.github.com/repos/" + repo + "/actions/secrets/public-key",
      headers: { "Authorization": "Bearer " + pat, "Accept": "application/vnd.github+json", "User-Agent": "xunuo-secrets-sync" }
    }, function (error, response, data) {
      var r = parseJson(data);
      if (error || !response || response.status === 401) {
        $notification.post("同步Git Secrets", "Token 无效或过期", "重新创建一个 Token 粘贴到 BoxJs 里");
        $done({});
        return;
      }
      if (response.status === 404) {
        $notification.post("同步Git Secrets", "仓库不存在或 Token 没权限", "检查仓库名，Token 要给这个仓库 Secrets 的读写权限");
        $done({});
        return;
      }
      if (!r || !r.key || !r.key_id) {
        $notification.post("同步Git Secrets", "拿不到仓库公钥", "HTTP " + (response && response.status));
        $done({});
        return;
      }
      var pubKey = b64decode(r.key);
      var keyId = r.key_id;
      var idx = 0;
      (function next() {
        if (idx >= queue.length) { finish(); return; }
        var item = queue[idx++];
        var encrypted;
        try {
          encrypted = b64encode(sealSecret(nacl.util.decodeUTF8(item.value), pubKey));
        } catch (e) {
          failed.push(item.name + "（加密失败）");
          next();
          return;
        }
        $httpClient.put({
          url: "https://api.github.com/repos/" + repo + "/actions/secrets/" + item.name,
          headers: { "Authorization": "Bearer " + pat, "Accept": "application/vnd.github+json", "Content-Type": "application/json", "User-Agent": "xunuo-secrets-sync" },
          body: JSON.stringify({ encrypted_value: encrypted, key_id: keyId })
        }, function (e2, r2, d2) {
          if (!e2 && r2 && (r2.status === 201 || r2.status === 204)) synced.push(item.name);
          else failed.push(item.name + "（HTTP " + (r2 && r2.status) + "）");
          next();
        });
      })();
    });
  }
}

function finish() {
  var lines = [];
  if (synced.length) lines.push("已上传 " + synced.length + " 个：" + synced.join("、"));
  if (failed.length) lines.push("失败 " + failed.length + " 个：" + failed.join("、"));
  if (skipped.length) lines.push("BoxJs 里空着、没上传：" + skipped.length + " 个");
  lines.push("GitHub Actions 每天 09:00 自动签到，不用挂梯子");
  $notification.post("同步Git Secrets", synced.length ? "上传完成" : "上传失败", lines.join("\n"));
  $done({});
}

})();
